<?php
include("auth_owner.php"); include("db.php"); include("functions.php");
$error="";$success="";$pwError="";$pwSuccess="";
$stmt=mysqli_prepare($conn,"SELECT u.email,u.phone,u.password,u.NID,p.full_name,p.address,p.date_of_birth FROM users u LEFT JOIN user_profiles p ON p.user_id=u.user_id WHERE u.user_id=? LIMIT 1"); mysqli_stmt_bind_param($stmt,"i",$owner_id); mysqli_stmt_execute($stmt); $profile=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); mysqli_stmt_close($stmt);
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['update_profile'])){
 $name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$dob=$_POST['date_of_birth']??'';
 if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone===''||$address===''||$dob==='')$error="Please complete all profile fields."; else {
  $stmt=mysqli_prepare($conn,"SELECT user_id FROM users WHERE email=? AND user_id<>? LIMIT 1");mysqli_stmt_bind_param($stmt,"si",$email,$owner_id);mysqli_stmt_execute($stmt);$dup=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);
  if($dup)$error="Email is already used by another account."; else {mysqli_begin_transaction($conn);try{$stmt=mysqli_prepare($conn,"UPDATE users SET email=?,phone=? WHERE user_id=?");mysqli_stmt_bind_param($stmt,"ssi",$email,$phone,$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,"UPDATE user_profiles SET full_name=?,address=?,date_of_birth=? WHERE user_id=?");mysqli_stmt_bind_param($stmt,"sssi",$name,$address,$dob,$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_commit($conn);$success="Profile updated.";$profile['full_name']=$name;$profile['email']=$email;$profile['phone']=$phone;$profile['address']=$address;$profile['date_of_birth']=$dob;}catch(Throwable $ex){mysqli_rollback($conn);$error="Update failed: ".$ex->getMessage();}}
 }
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['change_password'])){
 $currentPw=$_POST['current_password']??'';$newPw=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';
 if(!password_verify($currentPw,$profile['password']))$pwError="Current password is incorrect."; elseif(strlen($newPw)<6)$pwError="New password must be at least 6 characters."; elseif($newPw!==$confirm)$pwError="New password and confirmation do not match."; else {$hash=password_hash($newPw,PASSWORD_DEFAULT);$stmt=mysqli_prepare($conn,"UPDATE users SET password=? WHERE user_id=?");mysqli_stmt_bind_param($stmt,"si",$hash,$owner_id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$profile['password']=$hash;$pwSuccess="Password changed successfully.";}
}
$current='profile';
?>
