<section class="panel panel-narrow"><h2>Change Password</h2><?php if($pwError):?><div class="error-msg"><?php echo e($pwError); ?></div><?php endif;?><?php if($pwSuccess):?><div class="success-msg"><?php echo e($pwSuccess); ?></div><?php endif;?><form method="post" class="stacked-form"><input type="hidden" name="change_password" value="1"><label>Current Password</label><input type="password" name="current_password" required><label>New Password</label><input type="password" name="new_password" required><label>Confirm New Password</label><input type="password" name="confirm_password" required><button class="btn-login">CHANGE PASSWORD</button></form></section>
